// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Size} from "../src/Size.sol";

contract InvMutTest is Test {
    Size c;

    function setUp() public {
        c = new Size();
    }

    function testFuzz_property(address caller) public {
        // Any address is admissible as an observer of the paused flag.
        vm.assume(caller != address(0));

        // The protocol starts unpause-ed (deployed via new C(), initializers disabled,
        // and pause() was never called by anyone). Reading the public paused() view:
        vm.prank(caller);
        bool pausedFlag = c.paused();

        // General rule: a contract that has never been paused must report paused() == false,
        // regardless of who queries it.
        assertTrue(pausedFlag == false, "unpaused contract must report paused() == false");
    }
}
